(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.014+t*0.3)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.4)*8 + Math.cos((y+w1y)*0.02+t*0.35)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.38)*8 + Math.sin((x+w1x)*0.019-t*0.42)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.075, 2.1, 0.8],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.65)*55, 0.09, 1.8, 1.2],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.48+1)*95, 0.055, 2.4, 0.6],
    [120+Math.cos(t*0.75+1)*90, 180+Math.sin(t*0.55+3)*65, 0.11, 1.6, 1.0],
    [360+Math.sin(t*0.38+4)*100, 60+Math.cos(t*0.85+2)*75, 0.065, 2.7, 0.9],
    [240+Math.cos(t*0.32+5)*130, 200+Math.sin(t*0.5)*85, 0.085, 2.0, 1.1],
    [80+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+1)*50, 0.1, 1.4, 0.7],
    [400+Math.cos(t*0.42+2)*80, 220+Math.sin(t*0.58+4)*60, 0.07, 2.5, 1.3]
  ];
  let aS=0, iS=0, mS=0;
  for (const [sX,sY,f,sp,m] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.5)*m;
    mS += Math.sin(d*f*1.3-t*sp*0.8+2.5)*0.5;
  }
  const act=aS/8, inh=iS/8, mod=mS/8;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.036+t*0.95))/2
    +Math.sin((sx+sy)*0.11+t*2.2)*0.18+Math.sin((sx-sy)*0.09-t*1.8)*0.18
    +Math.sin(sx*0.06*sy*0.04+t*0.5)*0.12;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.038+ang*4.5-t*1.0))*0.35
    +Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const moire=Math.sin(sx*0.12+t*0.6)*Math.sin(sy*0.12-t*0.5)*Math.sin((sx+sy)*0.06+t*0.3);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5+moire*0.3)*1.6)*0.28;
  const rd1=act-inh*0.65+bg*0.28+spiral*0.35;
  const rd2=Math.tanh((mod+cell)*1.5)*0.4;
  const reaction=Math.tanh((rd1+rd2)*2.0);
  const sharp=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.3?1.05:0.95;
  const glow=Math.exp(-Math.abs(1-Math.abs(reaction))*3)*0.15;
  const v=reaction*0.5+0.5+glow;
  const pal=[[6,14,62],[12,55,95],[18,105,125],[28,155,148],[185,175,65],[205,115,60],[165,48,58],[95,18,48],[35,12,38],[6,14,62]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*sharp+glow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*sharp+glow*20)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*sharp+glow*40)|0)
  ];
}
